// Package manifest exposes the measured capabilities of OPA releases.
//
// Every OPA release has a manifest generated by tools/introspect which records
// the CLI command tree, flags, accepted Rego dialects and REST endpoints of
// that exact binary. OPA Studio uses the manifest to decide which features to
// offer, so the UI never shows an operation the OPA version cannot perform.
package manifest

import (
	"encoding/json"
	"fmt"
	"io/fs"
	"path"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"

	"github.com/alasgarovnamig/opa-studio/versions"
)

// Flag describes a single CLI flag.
type Flag struct {
	Short       string `json:"short,omitempty"`
	Type        string `json:"type"`
	Description string `json:"description"`
	Default     string `json:"default,omitempty"`
	Global      bool   `json:"global,omitempty"`
}

// Command describes a CLI (sub)command.
type Command struct {
	Description string              `json:"description"`
	Long        string              `json:"long,omitempty"`
	Usage       string              `json:"usage,omitempty"`
	Flags       map[string]Flag     `json:"flags"`
	Subcommands map[string]*Command `json:"subcommands,omitempty"`
}

// Endpoint is the observed behaviour of one REST endpoint.
type Endpoint struct {
	Method      string   `json:"method"`
	Path        string   `json:"path"`
	Status      int      `json:"status"`
	ContentType string   `json:"content_type,omitempty"`
	Keys        []string `json:"keys,omitempty"`
}

// Available reports whether the endpoint exists on the server.
// A JSON 404 means "route exists, document missing"; a text 404 means "no route".
func (e Endpoint) Available() bool {
	switch e.Status {
	case 0, 405:
		return false
	case 404:
		return strings.Contains(e.ContentType, "json")
	}
	return true
}

// Manifest is the introspection result for one OPA binary.
type Manifest struct {
	Schema        int               `json:"schema"`
	OPA           Release           `json:"opa"`
	VersionOutput map[string]string `json:"version_output"`
	CLI           struct {
		Commands  map[string]*Command `json:"commands"`
		RootFlags map[string]Flag     `json:"root_flags"`
	} `json:"cli"`
	Dialects struct {
		CLI    map[string]*bool `json:"cli"`
		Server map[string]bool  `json:"server"`
	} `json:"dialects"`
	PreferredDialect string                     `json:"preferred_dialect"`
	CLIFeatures      map[string]json.RawMessage `json:"cli_features"`
	Server           struct {
		Started          bool                `json:"started"`
		PreferredDialect string              `json:"preferred_dialect"`
		Endpoints        map[string]Endpoint `json:"endpoints"`
		Quirks           map[string]bool     `json:"quirks,omitempty"`
	} `json:"server"`
	Capabilities json.RawMessage `json:"capabilities,omitempty"`
	// Live is true when the manifest was built at runtime from an unknown binary.
	Live bool `json:"live,omitempty"`
}

// Release is the upstream release metadata stored in a manifest.
type Release struct {
	Version       string          `json:"version"`
	PublishedAt   string          `json:"published_at"`
	Prerelease    bool            `json:"prerelease"`
	GithubRelease bool            `json:"github_release"`
	Binary        json.RawMessage `json:"binary,omitempty"`
}

// HasCommand reports whether the CLI offers the named command.
func (m *Manifest) HasCommand(name string) bool {
	_, ok := m.CLI.Commands[name]
	return ok
}

// HasFlag reports whether command cmd accepts --flag.
func (m *Manifest) HasFlag(cmd, flag string) bool {
	c, ok := m.CLI.Commands[cmd]
	if !ok {
		return false
	}
	_, ok = c.Flags[flag]
	return ok
}

// VersionEntry is one element of versions/opa-versions.json.
type VersionEntry struct {
	Tag           string          `json:"tag"`
	PublishedAt   string          `json:"published_at"`
	Prerelease    bool            `json:"prerelease"`
	GithubRelease bool            `json:"github_release"`
	ReleaseURL    string          `json:"release_url"`
	Assets        []string        `json:"assets"`
	DockerImage   string          `json:"docker_image,omitempty"`
	Highlights    json.RawMessage `json:"highlights,omitempty"`
}

var (
	loadOnce sync.Once
	index    []VersionEntry
	loadErr  error
	cacheMu  sync.Mutex
	cache    = map[string]*Manifest{}
)

func load() {
	b, err := fs.ReadFile(versions.FS, "opa-versions.json")
	if err != nil {
		loadErr = err
		return
	}
	var doc struct {
		Versions []VersionEntry `json:"versions"`
	}
	if err := json.Unmarshal(b, &doc); err != nil {
		loadErr = err
		return
	}
	index = doc.Versions
}

// Versions returns every tracked OPA release in ascending semver order.
func Versions() ([]VersionEntry, error) {
	loadOnce.Do(load)
	return index, loadErr
}

// Normalize turns "1.0.0", "v1.0.0" or "Version: 1.0.0" into "v1.0.0".
func Normalize(v string) string {
	v = strings.TrimSpace(v)
	v = strings.TrimPrefix(v, "Version:")
	v = strings.TrimSpace(v)
	if v != "" && !strings.HasPrefix(v, "v") {
		v = "v" + v
	}
	return v
}

// Raw returns the manifest JSON for version v exactly as stored.
func Raw(v string) ([]byte, error) {
	return fs.ReadFile(versions.FS, path.Join("manifests", Normalize(v)+".json"))
}

// Get returns the parsed manifest for version v.
func Get(v string) (*Manifest, error) {
	v = Normalize(v)
	cacheMu.Lock()
	defer cacheMu.Unlock()
	if m, ok := cache[v]; ok {
		return m, nil
	}
	b, err := Raw(v)
	if err != nil {
		return nil, fmt.Errorf("no manifest for OPA %s: %w", v, err)
	}
	m := &Manifest{}
	if err := json.Unmarshal(b, m); err != nil {
		return nil, fmt.Errorf("parse manifest %s: %w", v, err)
	}
	cache[v] = m
	return m, nil
}

var semverRe = regexp.MustCompile(`^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?`)

// Compare compares two OPA versions semantically (-1, 0, 1).
func Compare(a, b string) int {
	pa, pb := semverRe.FindStringSubmatch(a), semverRe.FindStringSubmatch(b)
	if pa == nil || pb == nil {
		return strings.Compare(a, b)
	}
	for i := 1; i <= 3; i++ {
		x, _ := strconv.Atoi(pa[i])
		y, _ := strconv.Atoi(pb[i])
		if x != y {
			if x < y {
				return -1
			}
			return 1
		}
	}
	switch {
	case pa[4] == pb[4]:
		return 0
	case pa[4] == "":
		return 1
	case pb[4] == "":
		return -1
	}
	return strings.Compare(pa[4], pb[4])
}

// Nearest returns the newest known manifest version that is <= v. It is used
// when the binary is a build (e.g. a -dev snapshot) that has no exact manifest.
func Nearest(v string) string {
	vs, _ := Versions()
	best := ""
	for _, e := range vs {
		if Compare(e.Tag, v) <= 0 {
			best = e.Tag
		}
	}
	return best
}

var (
	commandLine = regexp.MustCompile(`^\s{2}([a-z][a-z0-9-]*)\s+(.*)$`)
	flagLine    = regexp.MustCompile(`^\s+(?:-([A-Za-z0-9]), )?--([A-Za-z0-9][A-Za-z0-9_.-]*)(?:\s+([A-Za-z0-9_{}<>|:,.\[\]-]+))?\s{2,}(.*)$`)
	defaultRe   = regexp.MustCompile(`\(default (.*)\)\s*$`)
)

// ParseCommands extracts the "Available Commands:" section of cobra help output.
func ParseCommands(text string) map[string]string {
	out := map[string]string{}
	in := false
	for _, line := range strings.Split(text, "\n") {
		s := strings.TrimSpace(line)
		if s == "Available Commands:" {
			in = true
			continue
		}
		if !in {
			continue
		}
		if s == "" {
			if len(out) > 0 {
				in = false
			}
			continue
		}
		if m := commandLine.FindStringSubmatch(line); m != nil {
			out[m[1]] = strings.TrimSpace(m[2])
		} else if !strings.HasPrefix(line, " ") {
			in = false
		}
	}
	return out
}

// ParseFlags extracts the "Flags:" and "Global Flags:" sections of cobra help output.
func ParseFlags(text string) map[string]Flag {
	out := map[string]Flag{}
	section := ""
	for _, line := range strings.Split(text, "\n") {
		s := strings.TrimSpace(line)
		if s == "Flags:" || s == "Global Flags:" {
			section = s
			continue
		}
		if section == "" {
			continue
		}
		if strings.HasPrefix(s, "Use \"") || strings.HasPrefix(s, "Additional help") {
			section = ""
			continue
		}
		m := flagLine.FindStringSubmatch(line)
		if m == nil {
			continue
		}
		f := Flag{Short: m[1], Type: m[3], Description: strings.TrimSpace(m[4]), Global: section == "Global Flags:"}
		if f.Type == "" {
			f.Type = "bool"
		}
		if d := defaultRe.FindStringSubmatch(f.Description); d != nil {
			f.Default = d[1]
		}
		out[m[2]] = f
	}
	return out
}

// UsageLine returns the line following "Usage:".
func UsageLine(text string) string {
	lines := strings.Split(text, "\n")
	for i, l := range lines {
		if strings.TrimSpace(l) == "Usage:" && i+1 < len(lines) {
			return strings.TrimSpace(lines[i+1])
		}
	}
	return ""
}

// HelpRunner runs the binary with the given args and returns combined output.
type HelpRunner func(args ...string) string

// Live builds a CLI-only manifest by parsing --help output of an arbitrary
// binary. Server endpoints are left empty which the UI treats as "unknown".
func Live(version string, run HelpRunner) *Manifest {
	m := &Manifest{Schema: 1, Live: true}
	m.OPA.Version = Normalize(version)
	m.CLI.Commands = map[string]*Command{}
	root := run("help")
	cmds := ParseCommands(root)
	if len(cmds) == 0 {
		cmds = ParseCommands(run("--help"))
	}
	names := make([]string, 0, len(cmds))
	for n := range cmds {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, name := range names {
		c := &Command{Description: cmds[name], Flags: map[string]Flag{}}
		if name != "help" && name != "completion" {
			h := run(name, "--help")
			c.Usage = UsageLine(h)
			c.Flags = ParseFlags(h)
			subs := ParseCommands(h)
			if len(subs) > 0 {
				c.Subcommands = map[string]*Command{}
				for s, d := range subs {
					if s == "help" {
						continue
					}
					sh := run(name, s, "--help")
					c.Subcommands[s] = &Command{Description: d, Usage: UsageLine(sh), Flags: ParseFlags(sh)}
				}
			}
		}
		m.CLI.Commands[name] = c
	}
	m.PreferredDialect = "v1"
	if Compare(m.OPA.Version, "v1.0.0") < 0 {
		m.PreferredDialect = "legacy-assign"
	}
	return m
}

// Summary is a compact description of one release for the compatibility matrix.
type Summary struct {
	Version     string          `json:"version"`
	PublishedAt string          `json:"published_at"`
	Prerelease  bool            `json:"prerelease"`
	Release     bool            `json:"github_release"`
	Dialect     string          `json:"dialect"`
	Commands    []string        `json:"commands"`
	Endpoints   []string        `json:"endpoints"`
	Builtins    int             `json:"builtins"`
	Flags       int             `json:"flags"`
	Quirks      []string        `json:"quirks,omitempty"`
	Highlights  json.RawMessage `json:"highlights,omitempty"`
	ReleaseURL  string          `json:"release_url"`
}

var (
	summaryOnce sync.Once
	summaries   []Summary
)

// Summaries returns one Summary per tracked release (ascending).
func Summaries() []Summary {
	summaryOnce.Do(func() {
		vs, _ := Versions()
		for _, v := range vs {
			m, err := Get(v.Tag)
			if err != nil {
				continue
			}
			s := Summary{Version: v.Tag, PublishedAt: v.PublishedAt, Prerelease: v.Prerelease, Release: v.GithubRelease, Dialect: m.PreferredDialect, ReleaseURL: v.ReleaseURL, Highlights: v.Highlights, Commands: []string{}, Endpoints: []string{}}
			for name, c := range m.CLI.Commands {
				if name == "help" || name == "completion" {
					continue
				}
				s.Commands = append(s.Commands, name)
				s.Flags += len(c.Flags)
			}
			sort.Strings(s.Commands)
			for k, e := range m.Server.Endpoints {
				if e.Available() {
					s.Endpoints = append(s.Endpoints, k)
				}
			}
			sort.Strings(s.Endpoints)
			for q, on := range m.Server.Quirks {
				if on {
					s.Quirks = append(s.Quirks, q)
				}
			}
			if len(m.Capabilities) > 0 && string(m.Capabilities) != "null" {
				var c struct {
					Builtins []json.RawMessage `json:"builtins"`
				}
				if json.Unmarshal(m.Capabilities, &c) == nil {
					s.Builtins = len(c.Builtins)
				}
			}
			summaries = append(summaries, s)
			// Free memory: the matrix only needs the summary.
			cacheMu.Lock()
			delete(cache, v.Tag)
			cacheMu.Unlock()
		}
	})
	return summaries
}
